package dev.mbapdu.tags;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.UUID;

/** Vectors are shared with native catalog tests, not generated by this codec. */
public final class CatalogTest {
    private static int checks;
    private static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static void rejected(Runnable action,String message){try{action.run();throw new AssertionError(message);}catch(IllegalArgumentException expected){checks++;}}
    private static CatalogWire.Summary summary(CatalogWire.Snapshot s){return CatalogWire.Summary.parse("CATALOG:"+s.revision+":"+s.count()+":"+s.hashHex().toLowerCase(java.util.Locale.ROOT));}
    public static int run(){
        String id="00112233-4455-6677-8899-aabbccddeeff";
        byte[] ndef=Protocol.hex("D101135402727548656C6C6F2D66726F6D2D506978656C");
        CatalogWire.Entry entry=new CatalogWire.Entry(id,9,"NFC-Test","","NDEF",ndef);
        CatalogWire.Snapshot snapshot=new CatalogWire.Snapshot(7,Collections.singletonList(entry));
        require(Protocol.hex(snapshot.bytes()).equals("544341540001000100000007003D00112233445566778899AABBCCDDEEFF000000090108000400174E46432D546573744E444546D101135402727548656C6C6F2D66726F6D2D506978656C"),"native golden snapshot bytes");
        require(snapshot.hashHex().equals("599AB419F874E160B013998284EF81CB93F5685BB153091282C84FC7EE9D4140"),"native golden snapshot SHA256");
        require(Protocol.hex(entry.ndefHash()).equals("71C395E4CB360CB7932EBDD8D625713788F35EA5CE691C2C9F5B8CFE760A4A82"),"native golden NDEF SHA256");
        byte[] begin=snapshot.begin();require(begin.length==42 && Protocol.hex(Arrays.copyOf(begin,10)).equals("0100000007010000004B"),"BEGIN exact BE header");
        require(Arrays.equals(Arrays.copyOfRange(begin,10,42),snapshot.hash()),"BEGIN digest covers exact snapshot");
        byte[] payload=snapshot.chunk(0);require(payload.length==80 && Protocol.hex(Arrays.copyOf(payload,5)).equals("0200000000"),"DATA opcode and BE offset");
        require(Arrays.equals(Arrays.copyOfRange(payload,5,payload.length),snapshot.bytes()),"DATA small fixture");
        rejected(()->snapshot.chunk(-1),"negative chunk offset");rejected(()->snapshot.chunk(75),"EOF chunk rejected");
        byte[] copy=snapshot.bytes();copy[0]=0;require(snapshot.bytes()[0]=='T',"snapshot defensive bytes");
        ndef[0]=0;require(entry.ndef()[0]==(byte)0xd1,"input NDEF defensive snapshot");
        copy=entry.ndef();copy[0]=0;require(entry.ndef()[0]==(byte)0xd1,"entry defensive bytes");
        CatalogWire.Snapshot empty=new CatalogWire.Snapshot(1,Collections.emptyList());
        require(empty.length()==12 && empty.hashHex().equals("7E9BDE1D501D706AB716163B5EBA4CA724BFE0A7EAE4AB70168E45E224664888"),"empty catalog golden");
        require(summary(snapshot).matches(snapshot),"summary matches exact revision,count,hash");
        require(!CatalogWire.Summary.parse("CATALOG:0:0:"+String.join("",Collections.nCopies(64,"0"))).matches(snapshot),"uninitialized remote not local");
        rejected(()->CatalogWire.Summary.parse("CATALOG:0:1:"+snapshot.hashHex()),"zero revision cannot contain records");
        rejected(()->CatalogWire.Summary.parse("CATALOG:4294967296:1:"+snapshot.hashHex()),"summary revision overflow");
        rejected(()->CatalogWire.Summary.parse("CATALOG:7:33:"+snapshot.hashHex()),"summary count overflow");
        rejected(()->CatalogWire.Summary.parse("CATALOG:7:1:ABC"),"summary truncated digest");
        rejected(()->CatalogWire.Summary.parse("CATALOG:7:1:"+snapshot.hashHex()+":extra"),"summary trailing data");
        rejected(()->new CatalogWire.Entry(id,0,"Name","","",null),"record revision zero");
        rejected(()->new CatalogWire.Entry(id,0x100000000L,"Name","","",null),"record revision overflow");
        rejected(()->new CatalogWire.Entry("00000000-0000-0000-0000-000000000000",1,"Name","","",null),"nil ID");
        rejected(()->new CatalogWire.Entry(id.toUpperCase(java.util.Locale.ROOT),1,"Name","","",null),"canonical UUID");
        rejected(()->new CatalogWire.Entry(id,1,"","","",null),"empty name");
        rejected(()->new CatalogWire.Entry(id,1,"Line\nBreak","","",null),"name controls");
        rejected(()->new CatalogWire.Entry(id,1,String.join("",Collections.nCopies(49,"я")),"","",null),"UTF8 byte bound");
        rejected(()->new CatalogWire.Entry(id,1,"Name","aa","",null),"lowercase UID rejected");
        rejected(()->new CatalogWire.Entry(id,1,"Name","ABC","",null),"odd UID rejected");
        rejected(()->new CatalogWire.Entry(id,1,"Name","","NFC\n",null),"tech controls");
        rejected(()->new CatalogWire.Entry(id,1,"Name","","",new byte[0]),"kind1 empty body rejected");
        rejected(()->new CatalogWire.Entry(id,1,"Name","","",new byte[1025]),"oversized NDEF");
        rejected(()->new CatalogWire.Snapshot(0,Collections.singletonList(entry)),"catalog revision zero");
        rejected(()->new CatalogWire.Snapshot(1,Arrays.asList(entry,entry)),"duplicate IDs");
        String unicode=CatalogWire.displayName(String.join("",Collections.nCopies(40,"😀")));
        require(unicode.codePointCount(0,unicode.length())==24 && unicode.getBytes(StandardCharsets.UTF_8).length==96,"UTF8 truncation at complete scalar");
        require(CatalogWire.displayName(" \nName\t ").equals("Name"),"display name control cleanup");
        ArrayList<CatalogWire.Entry> full=new ArrayList<>();
        for(int i=1;i<=32;i++)full.add(new CatalogWire.Entry(new UUID(0,i).toString(),0xffffffffL,String.join("",Collections.nCopies(48,"я")),"0123456789ABCDEF0123",String.join("",Collections.nCopies(48,"A")),new byte[1024]));
        CatalogWire.Snapshot maximum=new CatalogWire.Snapshot(0xffffffffL,full);
        require(maximum.length()==38924 && maximum.count()==32,"all maximum fields fit bounded snapshot");
        java.io.ByteArrayOutputStream reassembled=new java.io.ByteArrayOutputStream();
        for(int offset=0;offset<maximum.length();offset+=CatalogWire.CHUNK_BYTES){
            byte[] part=maximum.chunk(offset);require(part.length>=6&&part.length<=245,"chunk payload bounded");
            require(ByteBuffer.wrap(part,1,4).getInt()==offset,"contiguous chunk offsets");reassembled.write(part,5,part.length-5);
        }
        require(Arrays.equals(reassembled.toByteArray(),maximum.bytes()),"maximum catalog exact chunk reassembly");
        ArrayList<CatalogWire.Entry> over=new ArrayList<>(full);over.add(new CatalogWire.Entry(new UUID(0,33).toString(),1,"Name","","",null));
        rejected(()->new CatalogWire.Snapshot(1,over),"record count limit");
        CatalogWire.Selection selected=entry.selection(snapshot.revision);byte[] request=selected.payload(CatalogWire.SELECT_REQUEST);
        require(request.length==57 && Protocol.hex(Arrays.copyOf(request,25)).equals("010000000700112233445566778899AABBCCDDEEFF00000009"),"selection exact UUID/revision tuple");
        require(CatalogWire.Selection.parse(request,1).same(selected),"selection roundtrip");
        require(selected.matches(snapshot),"selection matches all identity fields");
        byte[] damaged=request.clone();damaged[56]^=1;require(!CatalogWire.Selection.parse(damaged,1).matches(snapshot),"NDEF hash mismatch blocks selection");
        damaged=request.clone();damaged[24]^=1;require(!CatalogWire.Selection.parse(damaged,1).matches(snapshot),"record revision mismatch blocks selection");
        damaged=request.clone();damaged[4]^=1;require(!CatalogWire.Selection.parse(damaged,1).matches(snapshot),"catalog revision mismatch blocks selection");
        for(int n=0;n<request.length;n++){final byte[] truncated=Arrays.copyOf(request,n);rejected(()->CatalogWire.Selection.parse(truncated,1),"truncated selection");}
        rejected(()->CatalogWire.Selection.parse(selected.payload(2),1),"ACK cannot become request");
        CatalogWire.Entry second=new CatalogWire.Entry(new UUID(0,99).toString(),1,"Card metadata","","NfcA",null);
        CatalogWire.Snapshot two=new CatalogWire.Snapshot(10,Arrays.asList(entry,second));
        SelectionGate gate=new SelectionGate();gate.local(two);
        rejected(()->gate.receive(3,entry.selection(10).payload(1)),"request before matching remote catalog rejected");
        gate.observed(summary(two));SelectionGate.Request first=gate.receive(3,entry.selection(10).payload(1));
        require(gate.authorized(id)==null,"request alone never authorizes START");
        SelectionGate.Request later=gate.receive(4,second.selection(10).payload(1));
        require(!gate.confirm(first),"late ACK for prior card cannot authorize current card");
        require(gate.confirm(later) && gate.authorized(second.id)!=null,"latest matching selection accepted");
        require(gate.authorized(id)==null && !gate.authorized(second.id).supported(),"wrong/metadata card cannot supply NDEF");
        require(Protocol.hex(second.ndefHash()).equals("E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"),"metadata hash is SHA256 empty");
        gate.disconnected();gate.observed(summary(two));require(gate.authorized(second.id)==null && !gate.confirm(later),"reconnect never restores prior authorization");
        first=gate.receive(5,entry.selection(10).payload(1));require(gate.confirm(first),"fresh reconnect request can authorize");
        gate.local(new CatalogWire.Snapshot(11,Arrays.asList(entry,second)));require(gate.authorized(id)==null,"catalog replacement invalidates selected record");
        gate.local(two);gate.observed(summary(two));first=gate.receive(6,entry.selection(10).payload(1));gate.invalidate();require(!gate.confirm(first),"STOP invalidates pending selection");
        CommandGate command=new CommandGate();command.begin(1,new String[]{"CAT_BEGIN","CAT_SAME:7"},false);command.status(1,"CAT_SAME:7");require(!command.complete(),"catalog same still requires ATT");command.write(1,true);require(command.complete()&&command.result().equals("CAT_SAME:7"),"idempotent BEGIN same revision");
        command.begin(2,new String[]{"CATALOG:"},true);command.write(2,true);command.status(2,"ERROR:catalog unavailable");require(command.failed(),"summary prefix cannot accept ERROR");
        command.begin(3,"SELECT_OK");command.status(3,"SELECT_OK");command.write(3,true);require(command.complete(),"selection requires both STATUS and ATT");
        byte[] frame=Protocol.encode(new Protocol.Frame(Protocol.CATALOG,0x5fffffffL,maximum.chunk(0)));
        Protocol.Parser parser=new Protocol.Parser();ArrayList<Protocol.Frame> got=new ArrayList<>();
        for(int i=0;i<frame.length;i+=20)parser.feed(Arrays.copyOfRange(frame,i,Math.min(frame.length,i+20)),got::add);
        require(got.size()==1&&got.get(0).payload.length==245,"catalog frame across ATT20");
        rejected(()->new Protocol.Frame(Protocol.CATALOG,1,new byte[262]),"catalog frame bounded to261");
        return checks;
    }
}
